// crates/infra/src/event_processor.rs
use futures::StreamExt;
use std::rc::Rc;

pub async fn process_event_stream(mut stream: impl Stream<Item = Event>) {
    while let Some(event) = stream.next().await {
        if event.is_relevant() {
            let enriched = enrich(event);
            let results = fetch_related(event.id).await;
            let _ = save_to_db(&enriched).await;
            println!("Processed event {}", event.id);
        }
    }
}
